def solution(input_str):
    lines = input_str.strip().split('\n')
    h, m, k = map(int, lines[0].split())
    h1, m1 = map(int, lines[1].split())
    h2, m2 = map(int, lines[2].split())

    num_digits_h = len(str(h - 1))
    num_digits_m = len(str(m - 1))

    def format_num(val, num_digits):
        return str(val).zfill(num_digits)

    def get_display(minute_val):
        hours = minute_val // m
        mins = minute_val % m
        return format_num(hours, num_digits_h) + ":" + format_num(mins, num_digits_m)

    start_minutes = h1 * m + m1
    end_minutes = h2 * m + m2

    # Convert to effective minute range accounting for day wrap
    if start_minutes <= end_minutes:
        total_transitions = end_minutes - start_minutes
    else:
        if end_minutes + h * m <= start_minutes + h * m:
            total_transitions = (end_minutes + h * m) - start_minutes
        else:
            return "0"

    if total_transitions <= 0:
        return "0"

    count = 0
    day_total_minutes = h * m

    # We iterate through transitions
    # Starting from start_minutes, checking transitions to next_minutes

    # Precompute displays for current and next minutes to avoid recomputing
    def next_minute_display(current_minutes):
        next_min = current_minutes + 1
        if next_min >= day_total_minutes:
            # wrap around to next day
            return get_display(0)
        else:
            return get_display(next_min)

    current_minutes = start_minutes

    for _ in range(total_transitions):
        current_display = get_display(current_minutes)
        next_display = next_minute_display(current_minutes)

        changes = sum(1 for c1, c2 in zip(current_display, next_display) if c1 != c2)

        if changes >= k:
            count += 1

        # Move to next minute (wrapping)
        current_minutes = (current_minutes + 1) % day_total_minutes

    return str(count)
