def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]

    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    neighbors.append((nr, nc))
        return neighbors

    def can_color(r, c, color):
        if grid[r][c] != '0':
            return False
        for nr, nc in get_neighbors(r, c):
            if grid[nr][nc] != '0' and grid[nr][nc] == str(color):
                return False
        return True

    def color_cell(r, c, color):
        grid[r][c] = str(color)

    def uncolor_cell(r, c):
        grid[r][c] = '0'

    def backtrack(idx):
        if idx == n * m:
            return True

        r, c = idx // m, idx % m

        if grid[r][c] != '0':
            return backtrack(idx + 1)

        for color in [1, 2, 3, 4]:
            if can_color(r, c, color):
                color_cell(r, c, color)
                if backtrack(idx + 1):
                    return True
                uncolor_cell(r, c)

        return False

    if backtrack(0):
        result = '\n'.join(''.join(row) for row in grid)
        return result
    else:
        return '0'

