def solution(input_str):
    import math
    from functools import reduce

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def find_divisors(n):
        divs = set()
        divs.add(n)
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divs.add(i)
                divs.add(n // i)
        return sorted(list(divs))

    def find_prime_factors(n):
        factors = []
        d = 2
        temp = n
        while d * d <= temp:
            if temp % d == 0:
                factors.append(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.append(temp)
        return factors

    def solve(n):
        divisors = find_divisors(n)
        factors = find_prime_factors(n)

        # Start with n in the order
        order = [n]
        used = {n}
        remaining = [d for d in divisors if d != n]

        # Group remaining divisors by which prime factor they're divisible by
        factor_groups = []
        for f in factors:
            group = [d for d in remaining if d % f == 0]
            factor_groups.append(group)

        # Sort each group
        for i in range(len(factor_groups)):
            factor_groups[i].sort()

        # Build order by appending groups sequentially
        for group in factor_groups:
            for d in group:
                if d not in used:
                    order.append(d)
                    used.add(d)

        # Calculate number of moves needed (coprime adjacent pairs in circle)
        moves = 0
        order_len = len(order)
        for i in range(order_len):
            prev = order[i]
            curr = order[(i + 1) % order_len]
            if gcd(prev, curr) == 1:
                moves += 1

        # Generate output string
        order_str = ' '.join(map(str, order))
        return f"{order_str}\n{moves}\n"

    # Parse input
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    test_cases = lines[1:]

    results = []
    for tc in test_cases[:t]:
        n = int(tc)
        result = solve(n)
        results.append(result)

    return '\n'.join(results)
