            topic = chain[idx]
            prereq = p[topic]
            if prereq != -1 and prereq != 0:
                if prereq in chain and chain.index(prereq) >= idx:
                    return "\n0\n"

    # Build chain dependency graph
    chain_indices = [-1] * n
    for ci, chain in enumerate(chains):
