    # Check if the array is already a geometric progression
    if is_geometric(arr):
        return "0"

    # Try removing each element and check if the rest form a geometric progression
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_geometric(new_arr):
