    finish_pos = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish_pos = (r, c)

    if finish_pos is None:
        return ""

    # Direction mappings: original button -> actual direction to move
    # (dr, dc) for each button
    # U, D, L, R buttons
    directions = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    # Create actual mapping based on swaps
    # If swap_lr is 1, L becomes R and R becomes L
    # If swap_ud is 1, U becomes D and D becomes U
    actual_moves = {}
    for btn, (dr, dc) in directions.items():
        if btn == 'L' and swap_lr:
            actual_moves[btn] = (dr, -dc)  # L becomes R
        elif btn == 'R' and swap_lr:
            actual_moves[btn] = (-dr, dc)   # R becomes L
        elif btn == 'U' and swap_ud:
            actual_moves[btn] = (-dr, dc)   # U becomes D
        elif btn == 'D' and swap_ud:
            actual_moves[btn] = (dr, -dc)   # D becomes U
        else:
            actual_moves[btn] = directions[btn]

    # BFS to find the shortest path from start to finish
    queue = collections.deque([(start_pos, [])])
    visited = set([start_pos])

    while queue:
        (r, c), path = queue.popleft()

        if (r, c) == finish_pos:
            return '\n'.join(path) + '\n'

        for btn, (dr, dc) in actual_moves.items():
            nr, nc = r + dr, c + dc

            # Handle boundary check - if out of range, position doesn't change
            if 0 <= nr < n and 0 <= nc < m:
                # Check if safe to visit (not dangerous)
                if grid[nr][nc] != '*':
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        new_path = path + [btn]
                        queue.append(((nr, nc), new_path))
            else:
                # Out of bounds - position doesn't change, so same state
                # Don't re-add to queue
                continue

    return ""  # Should not reach here given problem guarantees
