from functools import lru_cache

def solution(input_str):
    parts = input_str.strip().split()
    if len(parts) == 1 and '\n' in input_str:
        parts = input_str.replace('\n', ' ').strip().split()

    a, b, n = int(parts[0]), int(parts[1]), int(parts[2])

    # Memoization to avoid recomputing states
    memo = {}

    def is_losing_position(current_a, current_b):
        """Returns True if this is a losing position (current player to move loses with optimal play)"""
        # Calculate ways
        ways = current_a ** current_b

        # If already exceeded target, the player who MADE this move loses
        # So this state is not reachable by the current player as a "current" position
        if ways >= n:
            return True  # Terminal losing state

        if (current_a, current_b) in memo:
            return memo[(current_a, current_b)]

        # Try both possible moves
        can_force_win = False

        # Move 1: Add a box
        new_a1 = current_a + 1
        new_b1 = current_b
        if new_a1 ** new_b1 < n:
            # Opponent position - is it a winning position for opponent?
            # If opponent is in losing position, we win
            if not is_losing_position(new_a1, new_b1):
                can_force_win = True

        if not can_force_win:
            # Move 2: Add an item
            new_a2 = current_a
            new_b2 = current_b + 1
            if new_a2 ** new_b2 < n:
                if not is_losing_position(new_a2, new_b2):
                    can_force_win = True

        # If we can move to a losing position for opponent, we're in winning position
        is_winning = can_force_win
        memo[(current_a, current_b)] = not is_winning  # We want to return is_losing_position

        return memo[(current_a, current_b)]

    # If initial position is losing for Stas (first player), Masha wins = output "Stas"
    # If initial position is winning for Stas, Stas wins = output "Masha"
    # Based on the problem statement: "Output 'Stas' if Masha wins. Output 'Masha' if Stas wins."

    if is_losing_position(a, b):
