            # Check prefix ending at n - m
            ok = True
            total_c = 0
            for i in range(n - m):
                if not pref[i]:
                    ok = False
                    break
                total_c += pref_c[i]

            if ok:
                ans = min(ans, m * a + total_c * b)

        # Try removing middle segment [i, j)
        for i in range(n):
            for j in range(i + 1, n):
                # Keep [0, i) and [j, n)
                ok = True
                total_c = 0

                for k in range(i):
                    if not pref[k]:
                        ok = False
                        break
                    total_c += pref_c[k]
                if not ok:
                    continue

                for k in range(j, n):
                    if not suff[k]:
                        ok = False
                        break
                    total_c += suff_c[k]

                if ok:
                    ans = min(ans, (j - i) * a + total_c * b)
                    break  # move to next start position

    return str(max(0, int(ans)))
